-- Player-facing text (src/content/text-fields.ts): revision 1 of each document.
-- Never overwrites a document that already has a row (text saved on the admin page).

-- level:1.7
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:1.7', 1, '{"location":"Cổng Kiểm Soát","briefing":"[NHẬT KÝ HỆ THỐNG – CỔNG KIỂM SOÁT]\nLối ra cuối cùng của Vùng Tối. Mỗi tín hiệu phải qua ba vòng quét liên tiếp. Mỗi vòng, cổng nạp dữ liệu phiên khác và gửi hai câu hỏi mới qua kênh nhập. Trượt một vòng: bác cả lượt.\nNeural-ID phát sáu dòng. Mỗi dòng là một thành phần dựng ở sáu trạm trước. Luật của từng dòng nằm ở ô Mục tiêu.\nGói nào qua đủ ba vòng sẽ bị kiểm tay, bằng dữ liệu riêng của người trực.\nNgười trực ca đêm: NX-0417.","task_steps":["Bản nháp của Kai có sáu lệnh `print`, mỗi lệnh là một thành phần. Bấm CHẠY trước, rồi đọc terminal: vòng nào, dòng nào vỡ. Không sửa 4 dòng khóa.","Sửa từng dòng cho khớp luật ở ô Mục tiêu. Mỗi vòng, cổng đổi dữ liệu phiên và câu hỏi, nên đừng chép tay thứ gì cổng gửi.","Lượt chỉ đạt khi qua đủ ba vòng liên tiếp.","Xong khi cả 6 mục tiêu chuyển xanh ở cả ba vòng. Dùng không quá 9 câu lệnh và qua lượt kiểm tay của người trực thì được thêm sao."],"objectives":[{"line":1,"label":"Tiêu đề tín hiệu: giữ nguyên dòng tiêu đề trong bản nháp"},{"line":2,"label":"Hồ sơ danh tính: HO SO:, họ tên thật, dấu /, mã khu thật"},{"line":3,"label":"Khuôn kiểu: KHUON: rồi khuôn thật của mã phiên, đúng như print in ra"},{"line":4,"label":"Dữ liệu sinh trắc: SINH TRAC: rồi chiều cao × 2, làm tròn 2 chữ số thập phân"},{"line":5,"label":"Năng lượng tín hiệu: NANG LUONG: số pin đầy (mỗi pin 100 đơn vị), PIN +, phần lẻ còn lại"},{"line":6,"label":"Lời đáp xác thực: LOI DAP: rồi mã hỏi cộng 7"}],"hints":["Mỗi dòng in là một trạm Kai đã qua. Dòng nào vỡ cũng vỡ đúng như Kai từng vỡ ở trạm đó. Đọc terminal theo vòng: sửa dòng hỏng đầu tiên, chạy lại, rồi sang dòng kế.","Với mỗi dòng, tự hỏi ba câu: cổng có đổi thứ này giữa các vòng không? Nó đến dưới hình dạng nào? Phải đổi hình dạng trước khi tính không?\nDòng 2: cổng đang đọc tên ô nhớ, hay thứ nằm trong ô?\nDòng 3: khuôn chép tay còn đúng khi mã phiên đổi hình dạng không?\nDòng 4: chiều cao đến dưới dạng chữ. Nhân xong còn bao nhiêu chữ số sau dấu chấm?\nDòng 5: một pin đầy là 100 đơn vị. Số pin phải là số nguyên. Mức năng lượng có thể mang phần thập phân không?\nDòng 6: mã hỏi cũng đến dưới dạng chữ.","Mảnh tài liệu Python còn đọc được:\nten = \"Mai\"\nprint(f\"Chao {ten}\")   → Chao Mai\nprint(type(3.5))         → <class ''float''>\nint(float(\"9.0\"))       → 9\nround(1.2345, 2)         → 1.23\n17 // 5, 17 % 5          → 3, 2\ninput()                  → luôn trả về chuỗi\nMã đọc từ tên biến và từ kênh nhập thì đứng vững khi dữ liệu đổi. Mã chép tay thì không."],"reactions":{"entry":"Cổng Kiểm Soát. Ba vòng quét. Người trực đêm nay: NX-0417.","SyntaxError":"Dòng {line}. Trình dịch không đọc nổi câu này. Cổng chưa mở vòng nào.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng… là ngữ pháp.","TypeError":"Vòng {round}. Dòng {line}. TypeError. Một thành phần ép hai hình dạng vào cùng một phép tính. Thành phần đó dựng ở trạm nào?","ValueError":"Vòng {round}. Dòng {line}. ValueError. Thứ cổng gửi không chuyển sang được hình dạng đó.","NameError":"Vòng {round}. Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có. Soát từng ký tự.","ZeroDivisionError":"Vòng {round}. Dòng {line}. Chia cho không. Lõi từ chối.","AttributeError":"Vòng {round}. Dòng {line}. AttributeError. Thứ này không mang cái bạn đang gọi.","runtime_error":"Vòng {round}. Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Các dòng sau chưa kịp phát.","EOFError":"Vòng {round}. Dòng {line}. Cổng chỉ gửi hai câu hỏi. Mã của bạn đòi đọc thêm… kênh đã trống.","output_has_prompt":"Vòng {round}, dòng {out_line}. Lời nhắc của bạn cũng ra cổng, dính vào đầu dòng. Cổng tự hỏi… không cần ai nhắc.","output_is_label":"Vòng {round}, dòng {out_line}. Cổng đọc được tên ô nhớ… không phải thứ trong ô.","output_mismatch":"Vòng {round}, dòng {out_line}. Lệch từ ký tự thứ {col}. Cổng bác.","output_case_only":"Vòng {round}, dòng {out_line}. Đúng từng chữ… sai cỡ chữ. Cổng không bỏ qua.","output_missing":"Vòng {round}. Từ dòng {out_line} trở đi, cổng không nhận được gì.","output_extra":"Vòng {round}. Đủ sáu dòng, rồi thêm dòng ngoài giao thức. Cổng bác cả lượt.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi cổng ghi nhận.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở cổng này, chỉ có những gì bạn mang theo.","system_exit":"Chương trình tự dừng giữa chừng. Cổng không nhận được phần còn lại.","alert_exceeded":"Qua ba vòng. Nhưng {count} câu lệnh… Sentinel đã thấy. Viết gọn hơn.","counter_ValueError":"Người trực đưa một con số mang phần thập phân. Dòng {line} vỡ: ValueError.","counter_error":"Kiểm tay. Dòng {line}: {error_type}. Mã không chịu được dữ liệu của người trực.","wrong_value_counter":"Kiểm tay lệch. Dữ liệu của người trực khác mọi vòng trước… dòng {out_line} vẫn viết cho vòng cũ.","counter_timeout":"Mã treo lúc kiểm tay. Tôi cắt kết nối. Cổng chỉ mở một nửa.","two_stars":"Ba vòng. Không để lại dấu vết. Trong buồng trực, đèn vừa bật.","three_stars":"Người trực nhìn tín hiệu lâu hơn bình thường. Rồi đóng dấu.","repeated_fail":"Lần thứ {count}, cùng một lỗi. Mở mức gợi ý tiếp theo trong nhật ký.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc terminal theo từng vòng."},"reaction_variants":{"output_mismatch":"Vòng {round}, dòng {out_line} vẫn lệch, từ ký tự thứ {col}. Đặt dòng cần và dòng nhận cạnh nhau.","TypeError":"Vòng {round}, dòng {line}. Vẫn TypeError. Chữ và số vẫn đứng chung một phép tính.","wrong_value_counter":"Người trực vẫn thấy dòng {out_line} lệch. Dòng đó còn giữ thứ gì chép tay?"},"counter_attack_banner":"KIỂM TAY · NX-0417 NẠP DỮ LIỆU RIÊNG","outro":"Cổng mở. Người trực ca đêm đóng dấu tay lên tín hiệu của ĐỖ MINH AN.\nDưới sàn cổng, một hộc kỹ thuật bật khóa. Nó chỉ mở cho một Neural-ID đủ sáu thành phần. Bên trong còn một dòng log:","lore_fragment":"KTS-05: Tôi thiết kế Neural-ID. Mảnh Định danh nằm ở nơi chỉ một danh tính dựng bằng tay mới mở được, vì OMNI chưa bao giờ dựng thứ gì bằng tay. Với ai có người thân đã bị tái định hướng: tái định hướng là gán lại. Giá trị cũ chưa bị xóa ngay.","outro_beats":[{"kind":"kai","text":"Sau kính buồng trực, Nhi nhìn thẳng vào màn hình kiểm. Thẳng vào tôi. Em không nhận ra."},{"kind":"log","text":"DẤU DUYỆT NX-0417 · TRỄ MỘT NHỊP SO VỚI MỨC CHUẨN"},{"kind":"card","text":"MẢNH THUẬT TOÁN 1/8\nĐỊNH DANH"},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Chúc mừng. Tôi đã đợi ở đây từ trước khi bạn tới.\""},{"kind":"echo","text":"Tín hiệu 0xA7 phát ra từ chính hệ thống của cổng. Từ bên trong mạng của OMNI."},{"kind":"kai","text":"Tôi cất mảnh vào túi áo. Không trả lời."}],"knowledge_summary":{"title":"Tổng kết Chương 1: in, biến, kiểu, toán tử, đọc dữ liệu","sections":[{"heading":"In và chuỗi","body":"Mỗi lệnh `print` in ra một dòng. Dấu phẩy giữa các giá trị chèn một dấu cách, còn `+` nối hai chuỗi sát nhau. Từng ký tự đều có nghĩa, kể cả chữ hoa chữ thường."},{"heading":"Biến và gán lại","body":"Biến là một cái tên gắn với một giá trị. Gán lại thì tên giữ nguyên, giá trị đổi. Lệnh chạy sau thấy giá trị mới nhất."},{"heading":"Bốn kiểu và `type()`","body":"Chương 1 có bốn kiểu: `int`, `float`, `str`, `bool`. `type(x)` cho biết kiểu thật của `x`. Khi không chắc, hỏi `type()` thay vì đoán."},{"heading":"Đổi kiểu: `int()`, `float()`, `round()`","body":"`int()` và `float()` tạo một giá trị mới mang kiểu khác. `int()` không đọc được chuỗi có dấu chấm, nên chuỗi như `\"7.0\"` phải qua `float()` trước. `round(x, n)` làm tròn `x` tới `n` chữ số sau dấu chấm."},{"heading":"Toán tử số học","body":"`//` chia lấy phần nguyên, `%` lấy phần dư, `**` là lũy thừa. `/` luôn cho số thực, kể cả khi chia hết. Nhân chia làm trước, cộng trừ làm sau."},{"heading":"Đọc dữ liệu và trả lời: `input()` và f-string","body":"`input()` đọc một dòng và luôn trả về chuỗi; muốn tính thì đổi kiểu trước. f-string (chuỗi có chữ `f` đứng trước dấu nháy) đặt giá trị vào giữa chữ: Python thay `{…}` bằng giá trị của biểu thức bên trong."},{"heading":"Dữ liệu đổi, mã vẫn đúng","body":"Đừng chép tay giá trị vào mã. Đọc từ tên biến hoặc từ `input()`, để cùng một đoạn mã cho kết quả đúng với dữ liệu mới."}],"mistakes":[{"code":"print(\"Nid/2089\")","explain":"Python phân biệt chữ hoa chữ thường. Dòng in ra phải khớp từng ký tự."},{"code":"print(\"HO SO: {ho_ten} / {ma_khu}\")","explain":"Thiếu chữ `f` trước dấu nháy, nên `{ho_ten}` chỉ là chữ thường. Thêm `f` để Python thay tên biến bằng giá trị của nó."},{"code":"print(\"KHUON:\", \"<class ''int''>\")","explain":"Khuôn chép tay chỉ đúng khi mã phiên là số nguyên. In `type(ma_phien)` để có kiểu thật."},{"code":"print(f\"SINH TRAC: {chieu_cao * 2}\")","explain":"`chieu_cao` là chuỗi, nên `* 2` lặp chuỗi chứ không nhân. Đổi sang `float` trước, rồi bọc kết quả trong `round(..., 2)`."},{"code":"print(f\"NANG LUONG: {int(muc) / 100} PIN + {int(muc) % 100}\")","explain":"`/` luôn cho số thực. Muốn số pin đầy là số nguyên thì dùng `//`."},{"code":"print(f\"LOI DAP: {ma_hoi + 7}\")","explain":"`input()` trả về chuỗi, và Python không cộng chuỗi với số. Đổi `ma_hoi` sang `int` trước khi cộng."},{"code":"muc = int(input())","explain":"Dữ liệu nhập có dấu chấm thì `int()` báo lỗi. Đọc qua `float()` trước: `int(float(input()))`."}],"next":"Chương 2: Trạm Sentinel. Bạn sẽ học `if`, `elif`, `else` để mã tự chọn việc cần làm theo dữ liệu."}}', '2026-10-27T18:32:02.143Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:1.7' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
